package com.dynasty;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Copies audited player facts only; it never dispatches rewards or copies active control state. */
@Mod.EventBusSubscriber(modid = Dynasty.MODID)
public final class LegacyPlayerProgression {
    private static final String WINDOW = "dynasty_merit_kill_window";
    private static final String EARNED = "dynasty_merit_kill_earned";
    private static final String BLESSING = "DynastyXuanniaoBlessing";
    private static final List<String> FIRST_KILLS = List.of(
            "dragon_emperor", "undead_first_emperor", "nine_heaven_general", "dragon_king",
            "rebel_general", "eunuch_mastermind", "phoenix", "qilin", "nian_beast", "nine_tailed_fox");
    private static final Map<String, Integer> ROOT_TYPES = rootTypes();

    private LegacyPlayerProgression() {}

    @SubscribeEvent
    public static void clonePlayer(PlayerEvent.Clone event) {
        if (!(event.getOriginal() instanceof ServerPlayer oldPlayer)
                || !(event.getEntity() instanceof ServerPlayer newPlayer)
                || oldPlayer == newPlayer || !oldPlayer.getUUID().equals(newPlayer.getUUID())) return;
        List<String> invalid = copyAuditedRoot(oldPlayer.getPersistentData(), newPlayer.getPersistentData());
        if (!invalid.isEmpty()) {
            Dynasty.LOGGER.warn("[Dynasty] Skipped malformed legacy progression fields for {}: {}",
                    newPlayer.getUUID(), invalid);
        }
    }

    // Package access permits offline tests using real NBT, without constructing a player or world.
    static List<String> copyAuditedRoot(CompoundTag source, CompoundTag target) {
        List<String> invalid = new ArrayList<>();
        for (var entry : ROOT_TYPES.entrySet()) {
            copyTyped(source, target, entry.getKey(), entry.getValue(), invalid);
        }
        if (source.contains(BLESSING)) {
            if (source.hasUUID(BLESSING)) target.put(BLESSING, source.get(BLESSING).copy());
            else invalid.add(BLESSING);
        }
        // Preserve the economic budget's original timestamp and spent amount together.
        // Malformed/partial pairs are diagnosed, not silently converted into a new budget.
        // Anti-reset preservation is guaranteed here only for a well-typed pair.
        if (source.contains(WINDOW) || source.contains(EARNED)) {
            if (source.contains(WINDOW, Tag.TAG_LONG) && source.contains(EARNED, Tag.TAG_INT)) {
                target.put(WINDOW, source.get(WINDOW).copy());
                target.put(EARNED, source.get(EARNED).copy());
            } else {
                invalid.add(WINDOW + "/" + EARNED);
            }
        }
        CompoundTag persisted = source.getCompound(Player.PERSISTED_NBT_TAG);
        for (String boss : FIRST_KILLS) {
            String key = "dynasty_firstkill_" + boss;
            if (source.contains(key, Tag.TAG_BYTE) && source.getBoolean(key)
                    || persisted.contains(key, Tag.TAG_BYTE) && persisted.getBoolean(key)) {
                target.putBoolean(key, true);
            }
        }
        // Do not mutate inherited PlayerPersisted: Forge initially aliases the old Tag,
        // and existing whole-container Clone handlers may subsequently replace it.
        return List.copyOf(invalid);
    }

    private static void copyTyped(CompoundTag source, CompoundTag target, String key, int type,
                                  List<String> invalid) {
        if (!source.contains(key)) return;
        if (source.contains(key, type)) target.put(key, source.get(key).copy());
        else invalid.add(key);
    }

    private static Map<String, Integer> rootTypes() {
        Map<String, Integer> types = new LinkedHashMap<>();
        add(types, Tag.TAG_INT, "dynasty_merit", "dynasty_rank", "dynasty_loyalty", "dynasty_rebellion",
                "dynasty_boss_kinds", "DynastyEventMonsterKills");
        add(types, Tag.TAG_STRING, "dynasty_boss_kinds_list", "dynasty_festival_day");
        add(types, Tag.TAG_BYTE, "dynasty_manual_given");
        for (String key : List.of("keju", "minister", "army", "qilin", "dim_celestial", "dim_underworld")) {
            types.put("dynasty_merit_evt_" + key, (int) Tag.TAG_BYTE);
        }
        for (String key : List.of("dragon_crystal", "xuantian_jade", "dragon_emperor_seal", "emperor_bone",
                "jade", "phoenix_feather", "rebel_head", "eunuch_token", "sky_token", "jade_seal",
                "official_seal", "edict", "tiger_tally", "blueprint", "bronze_ingot", "silver_ingot",
                "refined_steel", "cinnabar")) {
            types.put("dynasty_merit_seen_" + key, (int) Tag.TAG_BYTE);
        }
        for (String key : List.of("gilded_mace", "supreme_sword", "seven_star_saber", "sunbow")) {
            types.put("dynasty_gift_" + key, (int) Tag.TAG_BYTE);
        }
        for (String boss : FIRST_KILLS) types.put("dynasty_firstkill_" + boss, (int) Tag.TAG_BYTE);
        for (int index = 0; index < 24; index++) {
            types.put("dq_p_" + index, (int) Tag.TAG_INT);
            types.put("dq_c_" + index, (int) Tag.TAG_BYTE);
        }
        for (String key : List.of("keju", "rank1", "minister", "army", "calm", "dim_celestial",
                "dim_underworld", "qilin", "rank9")) {
            types.put("dq_e_" + key, (int) Tag.TAG_BYTE);
        }
        return Map.copyOf(types);
    }

    private static void add(Map<String, Integer> types, int type, String... keys) {
        for (String key : keys) types.put(key, type);
    }
}

package com.dynasty.cod3;

import com.dynasty.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.living.*;
import net.minecraftforge.eventbus.api.*;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.registries.ForgeRegistries;
import java.util.*;

/** Capture the existing death pipeline, delay loot/XP, persist a journal until cleanup. */
@Mod.EventBusSubscriber(modid=Dynasty.MODID)
public final class BossDeathState extends SavedData {
    public static final String KEY="dynasty_cod3_death";
    private final Map<UUID,CompoundTag> entries=new LinkedHashMap<>();
    private final Set<UUID> pending=new LinkedHashSet<>();
    private final Set<UUID> recovered=new HashSet<>();
    public static BossDeathState get(ServerLevel l){return l.getDataStorage().computeIfAbsent(BossDeathState::load,BossDeathState::new,"dynasty_cod3_deaths");}
    static BossDeathState load(CompoundTag n){
        var state=new BossDeathState();
        for(var tag:n.getList("Entries",10)){
            var entry=((CompoundTag)tag).copy();
            if(!entry.hasUUID("Boss"))continue;
            var definition=Cod3Catalog.sequence("deaths",entry.getString("Type"));
            if(definition==null)continue;
            entry.putInt("Duration",definition.totalTicks());
            entry.remove("RetryAt"); // A persisted retry clock must not delay recovery after a time rewind.
            UUID id=entry.getUUID("Boss");state.entries.put(id,entry);
            if(!entry.getBoolean("Cleaned")){state.pending.add(id);state.recovered.add(id);}
        }
        return state;
    }
    @Override public CompoundTag save(CompoundTag n){var list=new ListTag();entries.values().forEach(entry->list.add(entry.copy()));n.put("Entries",list);return n;}
    public static boolean managed(LivingEntity boss){return boss.getPersistentData().getBoolean(KEY);}
    @SubscribeEvent(priority=EventPriority.HIGHEST)
    public static void death(LivingDeathEvent e){
        if(!(e.getEntity() instanceof Mob boss)||!(boss.level() instanceof ServerLevel l))return;
        // The army encounter owns victory, evacuation and loot receipts for these actors.
        if(boss.getPersistentData().hasUUID("ArmyEncounter"))return;
        var id=ForgeRegistries.ENTITY_TYPES.getKey(boss.getType());var def=Cod3Catalog.sequence("deaths",id.toString());if(def==null)return;
        var data=get(l);if(data.entries.containsKey(boss.getUUID()))return;
        var n=new CompoundTag();n.putBoolean("PreviousNoAi",boss.isNoAi());n.putBoolean("PreviousInvulnerable",boss.isInvulnerable());n.putUUID("Boss",boss.getUUID());n.putString("Sequence",def.id());n.putString("Type",id.toString());n.putLong("Start",l.getGameTime());n.putInt("Duration",def.totalTicks());n.putLong("Position",boss.blockPosition().asLong());n.put("Loot",new ListTag());n.putInt("XP",0);
        if(boss.getKillCredit()!=null)n.putUUID("Killer",boss.getKillCredit().getUUID());
        n.putInt("Facing",boss.getDirection().get2DDataValue());
        data.entries.put(boss.getUUID(),n);data.pending.add(boss.getUUID());data.setDirty();boss.getPersistentData().putBoolean(KEY,true);boss.setNoAi(true);boss.setInvulnerable(true);boss.setTarget(null);
        if(boss instanceof DynastyBossCombat.BarHolder holder)holder.dynastyBossBar().setVisible(false);
        // Do not cancel death: advancement/kill credit and other mod death hooks still run.
    }
    @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)
    public static void canceledDeath(LivingDeathEvent e){
        if(e.isCanceled()&&e.getEntity() instanceof Mob boss&&boss.level() instanceof ServerLevel l)rollback(l,boss);
    }
    private static void rollback(ServerLevel level,Mob boss){
        var data=get(level);var previous=data.entries.remove(boss.getUUID());data.pending.remove(boss.getUUID());data.recovered.remove(boss.getUUID());
        if(previous==null)return;
        boss.getPersistentData().remove(KEY);boss.setNoAi(previous.getBoolean("PreviousNoAi"));boss.setInvulnerable(previous.getBoolean("PreviousInvulnerable"));
        if(boss instanceof DynastyBossCombat.BarHolder holder)holder.dynastyBossBar().setVisible(true);
        data.setDirty();
    }
    @SubscribeEvent(priority=EventPriority.LOWEST)
    public static void drops(LivingDropsEvent e){
        if(!managed(e.getEntity())||!(e.getEntity().level() instanceof ServerLevel l))return;
        var d=get(l);var n=d.entries.get(e.getEntity().getUUID());if(n==null)return;
        if(!n.getBoolean("Captured")){var list=new ListTag();for(var drop:e.getDrops())list.add(drop.getItem().save(new CompoundTag()));n.put("Loot",list);n.putBoolean("Captured",true);d.setDirty();}
        e.getDrops().clear();
    }
    @SubscribeEvent(priority=EventPriority.LOWEST)
    public static void xp(LivingExperienceDropEvent e){
        if(!managed(e.getEntity())||!(e.getEntity().level() instanceof ServerLevel l))return;
        var d=get(l);var n=d.entries.get(e.getEntity().getUUID());if(n!=null&&!n.getBoolean("XPCaptured")){n.putInt("XP",e.getDroppedExperience());n.putBoolean("XPCaptured",true);d.setDirty();}e.setDroppedExperience(0);
    }
    @SubscribeEvent(priority=EventPriority.HIGHEST)
    public static void tickCorpse(LivingEvent.LivingTickEvent e){
        if(!managed(e.getEntity())||e.getEntity().level().isClientSide)return;
        // Prevent vanilla's 20-tick removal. State progression is independent of a loaded corpse.
        e.setCanceled(true);
    }
    @SubscribeEvent public static void server(TickEvent.LevelTickEvent e){
        if(e.phase==TickEvent.Phase.END&&e.level instanceof ServerLevel level)settle(level);
    }
    static void settle(ServerLevel l){
        var data=get(l);var iterator=data.pending.iterator();
        while(iterator.hasNext()){
            var uuid=iterator.next();var n=data.entries.get(uuid);long age=l.getGameTime()-n.getLong("Start");
            Entity entity=l.getEntity(uuid);
            boolean recovery=data.recovered.contains(uuid);
            if(entity instanceof Mob revived&&revived.isAlive()){
                // Resurrection may happen after LivingDeathEvent. Never freeze a revived mob.
                iterator.remove();data.entries.remove(uuid);data.recovered.remove(uuid);revived.getPersistentData().remove(KEY);
                revived.setNoAi(n.getBoolean("PreviousNoAi"));revived.setInvulnerable(n.getBoolean("PreviousInvulnerable"));
                if(revived instanceof DynastyBossCombat.BarHolder holder)holder.dynastyBossBar().setVisible(true);
                data.setDirty();continue;
            }
            if(!recovery&&entity instanceof Mob boss&&age>=0&&age<n.getInt("Duration")){
                var def=Cod3Catalog.sequence("deaths",n.getString("Type"));
                if(def!=null)for(var step:def.steps())if(age==step.startTick()&&step.allowedDuringDeath())try{if(step.type()==BossSequenceDefinition.Type.SPAWN_CLIENT_VFX)Cod3Vfx.sequence(boss,def.id(),(int)age,step);else BossSequenceRunner.play(boss,step);}catch(RuntimeException ex){Dynasty.LOGGER.warn("cod3 death effect skipped",ex);}
            }
            if(!recovery&&age>=0&&age<n.getInt("Duration")&&!n.getBoolean("RewardGranted"))continue;
            if(n.getLong("RetryAt")>l.getGameTime())continue;
            BlockPos pos=BlockPos.of(n.getLong("Position"));if(!l.hasChunkAt(pos))continue;
            try {
                if(!n.getBoolean("RewardGranted")){
                    reward(l,pos,n);n.putBoolean("RewardGranted",true);data.setDirty();
                    if(entity instanceof Mob boss)boss.getPersistentData().putBoolean("dynasty_reward_granted",true);
                }
                if(!n.getBoolean("FirstKillGranted")&&n.hasUUID("Killer")){
                    var player=l.getServer().getPlayerList().getPlayer(n.getUUID("Killer"));
                    if(player!=null){DynastyBossCombat.grantFirstKill(player,new net.minecraft.resources.ResourceLocation(n.getString("Type")).getPath());n.putBoolean("FirstKillGranted",true);data.setDirty();}
                }
                if(!n.getBoolean("WorldApplied")){Cod3WorldState.bossDefeated(l,n.getString("Type"));n.putBoolean("WorldApplied",true);data.setDirty();}
                if(entity!=null)entity.remove(Entity.RemovalReason.KILLED);
                // Keep completion tombstones so a stale saved corpse cannot generate another reward.
                n.putBoolean("Cleaned",true);iterator.remove();data.recovered.remove(uuid);data.setDirty();
            }catch(RuntimeException ex){n.putLong("RetryAt",l.getGameTime()+20);data.setDirty();Dynasty.LOGGER.error("cod3 reward remains pending boss={}",uuid,ex);}
        }
    }
    @SubscribeEvent public static void login(net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent event){
        if(!(event.getEntity() instanceof net.minecraft.server.level.ServerPlayer player))return;
        for(var level:player.server.getAllLevels()){
            var data=get(level);
            for(var n:data.entries.values())if(n.getBoolean("RewardGranted")&&!n.getBoolean("FirstKillGranted")&&n.hasUUID("Killer")&&n.getUUID("Killer").equals(player.getUUID())){
                DynastyBossCombat.grantFirstKill(player,new net.minecraft.resources.ResourceLocation(n.getString("Type")).getPath());n.putBoolean("FirstKillGranted",true);data.setDirty();
            }
        }
    }
    @SubscribeEvent public static void join(net.minecraftforge.event.entity.EntityJoinLevelEvent e){
        if(!(e.getEntity() instanceof Mob boss)||!(e.getLevel() instanceof ServerLevel l))return;
        var n=get(l).entries.get(boss.getUUID());
        if(n!=null&&n.getBoolean("Cleaned"))e.setCanceled(true);
        else if(n!=null){boss.getPersistentData().putBoolean(KEY,true);boss.setNoAi(true);boss.setInvulnerable(true);boss.setTarget(null);}
        else if(managed(boss)){boss.getPersistentData().remove(KEY);boss.setNoAi(false);boss.setInvulnerable(false);}
    }
    @SubscribeEvent public static void tracking(net.minecraftforge.event.entity.player.PlayerEvent.StartTracking e){
        if(e.getEntity() instanceof net.minecraft.server.level.ServerPlayer p&&e.getTarget() instanceof Mob boss&&managed(boss)&&boss.level() instanceof ServerLevel level){
            var state=get(level).entries.get(boss.getUUID());if(state!=null&&!state.getBoolean("Cleaned"))Cod3Vfx.sync(p,boss,state.getString("Sequence"),(int)(level.getGameTime()-state.getLong("Start")),state.getInt("Duration"));
        }
    }
    private static void reward(ServerLevel l,BlockPos pos,CompoundTag n){
        if(n.getBoolean("LootPlaced")&&n.getBoolean("XPAwarded"))return;
        boolean statue=n.getString("Type").equals("dynasty:rebel_general");
        BlockPos place=null;
        for(int dy=0;dy<4&&place==null;dy++)for(int dx=-2;dx<=2&&place==null;dx++)for(int dz=-2;dz<=2;dz++){
            var p=pos.offset(dx,dy,dz);if(l.getBlockState(p).isAir()&&(!statue||l.getBlockState(p.above()).isAir())&&l.getBlockState(p.below()).isSolidRender(l,p.below())){place=p;break;}
        }
        // A low ceiling must not destroy terrain or prevent the existing reward from settling.
        if(statue&&place==null){statue=false;for(int dy=0;dy<4&&place==null;dy++)for(int dx=-2;dx<=2&&place==null;dx++)for(int dz=-2;dz<=2;dz++){
            var p=pos.offset(dx,dy,dz);if(l.getBlockState(p).isAir()&&l.getBlockState(p.below()).isSolidRender(l,p.below())){place=p;break;}
        }}
        var stacks=new ArrayList<ItemStack>();for(var tag:n.getList("Loot",10))stacks.add(ItemStack.of((CompoundTag)tag));
        if(!n.getBoolean("LootPlaced")){
            // Phase receipts prevent a later XP/world-feedback failure from re-placing loot.
            // SavedData and chunks still use Minecraft's normal save boundary.
            if(place!=null&&statue&&RebelStatueBlock.place(l,place,n.contains("Facing")?net.minecraft.core.Direction.from2DDataValue(n.getInt("Facing")):net.minecraft.core.Direction.NORTH,stacks,n.getUUID("Boss"))){
                // Existing drops live in the memorial; pulling its blade consumes that exact stack.
            }else if(place!=null&&l.setBlock(place,LootableRemains.BLOCK.get().defaultBlockState(),3)&&l.getBlockEntity(place) instanceof LootableRemains.Remains remains){
                int i=0;for(var s:stacks){if(i<54)remains.setItem(i++,s);else net.minecraft.world.level.block.Block.popResource(l,place,s);}remains.setChanged();
            }else for(var s:stacks)net.minecraft.world.level.block.Block.popResource(l,pos,s);
            n.putBoolean("LootPlaced",true);get(l).setDirty();
        }
        if(!n.getBoolean("XPAwarded")){ExperienceOrb.award(l,net.minecraft.world.phys.Vec3.atCenterOf(pos),n.getInt("XP"));n.putBoolean("XPAwarded",true);get(l).setDirty();}
    }
}

package com.dynasty.dungeon;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/** Cores own room clocks. Markers use loaded-only bindings and authoritative visual snapshots. */
public final class DungeonMechanismBlockEntity extends BlockEntity {
    private UUID instance;
    private String roomId="probe",mechanismId="";
    private BlockPos controller=BlockPos.ZERO,areaMin,areaMax,destination,environmentOrigin,encounterOrigin;
    private int symbol=-1,requiredTargets=63;
    private boolean timedTrial;
    private final List<BlockPos> markers=new ArrayList<>();
    private boolean registered;
    private int visualPhase,visualTicks,visualDuration=1,doorTicks=12;
    private long visualTime;
    private boolean visualPaused;
    public DungeonMechanismBlockEntity(BlockPos pos,BlockState state){super(DungeonContent.MECHANISM.get(),pos,state);}
    public void configure(UUID instance,String room,String mechanism,BlockPos core,int symbol,List<BlockPos> markerPositions){
        this.instance=instance;roomId=room;mechanismId=mechanism;controller=core.immutable();this.symbol=symbol>=0&&symbol<=5?symbol:-1;
        environmentOrigin=null;encounterOrigin=null;
        markers.clear();markers.addAll(markerPositions.stream().filter(p->p.closerThan(core,128)).distinct().limit(64).toList());
        registered=false;setChanged();
    }
    public void configureEnvironment(BlockPos origin) {
        environmentOrigin=kind()==DungeonMechanismBlock.Kind.CORE&&ChenshaEnvironment.validCore(roomId,worldPosition,origin)?origin.immutable():null;
        setChanged();
    }
    public void configureEncounter(BlockPos origin){
        encounterOrigin=validBinding()&&(kind()==DungeonMechanismBlock.Kind.CORE||kind()==DungeonMechanismBlock.Kind.COFFIN)
            &&DungeonEncounters.validChenshaBinding(roomId,worldPosition,origin,kind()==DungeonMechanismBlock.Kind.COFFIN)
            &&controller.equals(origin.offset(ChenshaPiece.core("imperial_vault")))?origin.immutable():null;
        setChanged();
    }
    public void configureRoom(int targets,boolean timed,BlockPos min,BlockPos max){
        requiredTargets=targets&63;timedTrial=timed;
        if(min.closerThan(controller,128)&&max.closerThan(controller,128)){areaMin=min.immutable();areaMax=max.immutable();}
        registered=false;setChanged();
    }
    public void setDestination(BlockPos dest){if(dest.closerThan(worldPosition,128)){destination=dest.immutable();setChanged();}}
    public UUID instance(){return instance;}
    public String roomId(){return roomId;}
    public String mechanismId(){return mechanismId;}
    public boolean validBinding(){return instance!=null&&!roomId.isBlank()&&worldPosition.closerThan(controller,128);}
    private DungeonRoomController room(){return validBinding()&&level instanceof ServerLevel sl?DungeonStateStore.get(sl).room(instance,roomId):null;}
    public DungeonMechanismBlock.Kind kind(){return ((DungeonMechanismBlock)getBlockState().getBlock()).kind();}
    private boolean hazard(){return kind()==DungeonMechanismBlock.Kind.FLOOR||kind()==DungeonMechanismBlock.Kind.TRAP;}
    private DungeonHazard clock(DungeonRoomController room){return room.hazard(mechanismId,kind()==DungeonMechanismBlock.Kind.FLOOR);}
    private void changed(){if(level instanceof ServerLevel sl)DungeonStateStore.get(sl).setDirty();setChanged();}
    public void interact(Player player){
        if(level==null||level.isClientSide||!player.isAlive()||player.isSpectator()||player.distanceToSqr(Vec3.atCenterOf(worldPosition))>36)return;
        var state=room();if(state==null)return;
        if(kind()==DungeonMechanismBlock.Kind.TRAP&&useMaterial(player,state))return;
        if(kind()==DungeonMechanismBlock.Kind.COFFIN&&level instanceof ServerLevel sl
                &&player instanceof net.minecraft.server.level.ServerPlayer serverPlayer&&encounterOrigin!=null){
            var result=DungeonEncounters.claimChensha(sl,instance,encounterOrigin,serverPlayer);
            player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.dungeon.coffin."+result.name().toLowerCase(java.util.Locale.ROOT)),true);
        }else if(kind()==DungeonMechanismBlock.Kind.SEAL){if(state.recordTarget(symbol)){changed();syncVisual(state);}}
        else if(kind()==DungeonMechanismBlock.Kind.SHORTCUT){
            if(!player.getMainHandItem().is(net.minecraft.tags.ItemTags.PICKAXES)){
                player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.dungeon.stele_pickaxe"),true);return;
            }
            if(state.unlockShortcut(mechanismId)){
                // Individual broken-stone visuals and a shared permanent route use separate keys.
                state.unlockShortcut(sharedShortcutKey());
                changed();level.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.STONE_BREAK,net.minecraft.sounds.SoundSource.BLOCKS,1,.65F);
            }
            syncVisual(state);
        }else if(kind()==DungeonMechanismBlock.Kind.ELEVATOR){
            if(!state.shortcutOpen(mechanismId)){
                player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.dungeon.lift_locked"),true);return;
            }
            syncVisual(state);
            if(player.isShiftKeyDown()&&player.getMainHandItem().is(com.dynasty.expansion.ExpansionContent.item("qimen_cable")))useCargoLift(player);
            else useElevator(player);
        }else if(kind()==DungeonMechanismBlock.Kind.CORE){player.displayClientMessage(net.minecraft.network.chat.Component.literal(
            "破封 "+Integer.bitCount(state.progress()&7)+"/3，兽眼 "+Integer.bitCount((state.progress()>>3)&7)+"/3"),true);}
    }
    private boolean useMaterial(Player player,DungeonRoomController state){
        var held=player.getMainHandItem();boolean gear=held.is(com.dynasty.expansion.ExpansionContent.item("qimen_gear"));
        boolean cable=held.is(com.dynasty.expansion.ExpansionContent.item("qimen_cable"));
        if(!gear&&!cable)return false;
        // A stale or forged marker cannot manufacture a new remote room or force its core chunk to load.
        if(!player.isAlive()||!loadedCore())return true;
        var clock=clock(state);boolean changed=false;
        if(gear)changed=clock.fitWarningGear();
        else if(clock.phase()==DungeonMechanism.Phase.IDLE){clock.trigger(level.getGameTime());changed=clock.phase()==DungeonMechanism.Phase.WARNING;}
        if(changed){
            if(!player.getAbilities().instabuild)held.shrink(1);
            changed();syncVisual(state);
            player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.cod4."+(gear?"trap_gear_fitted":"trap_cable_triggered")),true);
        }else player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.cod4.trap_material_no_change"),true);
        return true;
    }
    private boolean loadedCore(){
        return level instanceof ServerLevel sl&&sl.getChunkSource().getChunkNow(controller.getX()>>4,controller.getZ()>>4)!=null
            &&sl.getBlockEntity(controller) instanceof DungeonMechanismBlockEntity core&&core.kind()==DungeonMechanismBlock.Kind.CORE
            &&java.util.Objects.equals(instance,core.instance)&&roomId.equals(core.roomId);
    }
    /** Optional cargo uses the original unlocked lift/destination and the actual dropped entity, never a copied inventory. */
    private void useCargoLift(Player player){
        if(!player.isAlive()||!loadedCore()||!(level instanceof ServerLevel sl)||destination==null){cargoUnavailable(player);return;}
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)if(sl.getChunkSource().getChunkNow((destination.getX()+x)>>4,(destination.getZ()+z)>>4)==null){cargoUnavailable(player);return;}
        var arrival=Vec3.atBottomCenterOf(destination);
        var candidates=sl.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(worldPosition).inflate(2),
            e->e.isAlive()&&!e.getItem().isEmpty()&&e.distanceToSqr(arrival)>1)
            .stream().sorted(java.util.Comparator.comparingDouble(e->e.distanceToSqr(Vec3.atCenterOf(worldPosition)))).limit(8).toList();
        for(var cargo:candidates){
            // Native pickup ownership is in the actual entity save; inspect at most eight candidates.
            var saved=cargo.saveWithoutId(new CompoundTag());
            if(saved.hasUUID("Owner")&&!saved.getUUID("Owner").equals(player.getUUID()))continue;
            AABB landing=cargo.getBoundingBox().move(arrival.subtract(cargo.position()));
            if(!sl.getWorldBorder().isWithinBounds(landing)||!sl.noCollision(cargo,landing)
                ||!sl.getBlockState(destination.below()).isFaceSturdy(sl,destination.below(),net.minecraft.core.Direction.UP)
                ||!sl.getFluidState(destination).isEmpty())continue;
            cargo.teleportTo(arrival.x,arrival.y,arrival.z);cargo.setDeltaMovement(Vec3.ZERO);cargo.fallDistance=0;
            if(cargo.isAlive()&&cargo.distanceToSqr(arrival)<.01){
                if(!player.getAbilities().instabuild)player.getMainHandItem().shrink(1);
                player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.cod4.lift_cargo_sent"),true);return;
            }
        }
        cargoUnavailable(player);
    }
    private static void cargoUnavailable(Player player){player.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.cod4.lift_cargo_unavailable"),true);}

        net.minecraft.server.level.ServerBossEvent dynastyBossBar();
    }

